 public static bool Running{get;private set;}
 static WorkerSelectUI ui;static WorkerRuntimeAgent agent;static ShipyardExploreCameraController e;static WorkerRouteRenderer route;
 static Keyboard keyboard;static InputSettings original,temp;static HideFlags flags;static InputDevice[] physical;static bool background;static int rate;
 static int stage,stageFrame,lastFrame,profileIndex,language,unsafeIndex,pendingChoice=-1,choiceFrame;static float started;static string output,error,rootPose;static int playerId,characterId,cameraId,targetId,interactionId,cameraCount;static Vector3 center;static float height,radius,step,eye;
