  var b=Button(name);Canvas.ForceUpdateCanvases();var r=b.GetComponent<RectTransform>();var p=new PointerEventData(EventSystem.current){position=RectTransformUtility.WorldToScreenPoint(null,r.TransformPoint(r.rect.center)),button=PointerEventData.InputButton.Left};var hits=new List<RaycastResult>();EventSystem.current.RaycastAll(p,hits);
  Require(hits.Count>0&&ExecuteEvents.GetEventHandler<IPointerClickHandler>(hits[0].gameObject)==b.gameObject,"Pointer blocked: "+name+" hits="+string.Join(",",hits.Select(h=>h.gameObject.name)));
  ExecuteEvents.Execute(b.gameObject,p,ExecuteEvents.pointerDownHandler);ExecuteEvents.Execute(b.gameObject,p,ExecuteEvents.pointerUpHandler);ExecuteEvents.Execute(b.gameObject,p,ExecuteEvents.pointerClickHandler);
 }
 static void SelectRenderedCard(int index){Click("WorkerCard_"+agent.profiles[index].workerId);Click("SelectActiveWorker");if(index==1)aCountBeforeB=agent.StateFor("WKR_SIGNAL_01").routeSession?.sampledPositions.Count??0;if(index==0)bCountAfter=agent.StateFor("WKR_RIG_01").routeSession?.sampledPositions.Count??0;}
