  if(!Application.isPlaying||Running)throw new Exception("Fresh Play required");output=folder;Directory.CreateDirectory(output);ui=UnityEngine.Object.FindFirstObjectByType<WorkerSelectUI>();agent=ui.agent;e=agent.explorer;route=ui.routeRenderer;
  e.shipyard.selection.SelectFacility(e.shipyard.catalog.Find(10));e.shipyard.overview.EnterFacility();e.Enter(true);
  playerId=e.player.GetInstanceID();characterId=e.character.GetInstanceID();cameraId=e.exploreCamera.GetInstanceID();targetId=e.firstPivot.GetInstanceID();interactionId=e.interactionOrigin.GetInstanceID();cameraCount=UnityEngine.Object.FindObjectsByType<Camera>(FindObjectsInactive.Include,FindObjectsSortMode.None).Length;height=e.character.height;radius=e.character.radius;center=e.character.center;step=e.character.stepOffset;eye=e.eyeHeight;rootPose=RootPose();pivots=new[]{GameObject.Find("SlewPivot").transform,GameObject.Find("TrolleyCarriage").transform,GameObject.Find("HookBlock").transform};
  original=InputSystem.settings;flags=original.hideFlags;if(flags==HideFlags.HideAndDontSave)original.hideFlags=HideFlags.DontSave;temp=UnityEngine.Object.Instantiate(original);temp.hideFlags=HideFlags.DontSave;temp.editorInputBehaviorInPlayMode=InputSettings.EditorInputBehaviorInPlayMode.AllDeviceInputAlwaysGoesToGameView;temp.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;InputSystem.settings=temp;
  physical=InputSystem.devices.Where(d=>d.enabled&&(d is Keyboard||d is Mouse)).ToArray();foreach(var d in physical)InputSystem.DisableDevice(d);keyboard=InputSystem.AddDevice<Keyboard>("Phase2AWorkerKeyboard");keyboard.MakeCurrent();background=Application.runInBackground;rate=Application.targetFrameRate;Application.runInBackground=true;Application.targetFrameRate=60;
