 static void Identity()
 {
  Require(e.player.GetInstanceID()==playerId&&e.character.GetInstanceID()==characterId&&e.exploreCamera.GetInstanceID()==cameraId,"Player/controller/camera replaced");Require(e.character.height==height&&e.character.radius==radius&&e.character.center==center&&e.character.stepOffset==step,"Character dimensions changed");Require(Mathf.Abs(height-1.8f)<.001f&&Mathf.Abs(radius-.28f)<.001f&&Mathf.Abs(center.y-.9f)<.001f&&Mathf.Abs(step-.25f)<.001f,"Character initial values wrong");Require(e.firstPivot.GetInstanceID()==targetId&&e.interactionOrigin.GetInstanceID()==interactionId&&e.eyeHeight==eye&&Mathf.Abs(eye-1.7f)<.001f,"Camera target/eye height changed");Require(UnityEngine.Object.FindObjectsByType<CharacterController>(FindObjectsInactive.Include,FindObjectsSortMode.None).Length==1,"Multiple CharacterControllers");Require(UnityEngine.Object.FindObjectsByType<Camera>(FindObjectsInactive.Include,FindObjectsSortMode.None).Length==cameraCount,"New worker camera created");
 }
 static void InjectUnsafe()
 {
  var entry=FacilityEntrance.ForFacility(e.shipyard.catalog.Find(10));Vector3 bad;
  if(unsafeIndex==0){var wall=entry.facility.GetComponentsInChildren<BoxCollider>(true).Where(c=>c.enabled&&!c.isTrigger&&c!=entry.closedDoorCollider&&((1<<c.gameObject.layer)&e.solidMask.value)!=0&&c.bounds.size.y>1).OrderBy(c=>Vector3.Distance(c.bounds.center,entry.transform.position)).First();bad=wall.bounds.center;bad.y=e.player.position.y;}
  else if(unsafeIndex==1)bad=new Vector3(110,0,110);else bad=entry.transform.TransformPoint(new Vector3(entry.clearWidth*.5f,0,0));
  Require(!agent.IsSafePosition(bad),"Unsafe fixture was not actually invalid");var state=agent.StateFor("WKR_RIG_01");state.hasPosition=true;state.lastPosition=bad;state.currentFacilityId="F10";state.exploreFacilityId="F10";Choose(1);Advance(11);
 }
 static void Send(string action)
 {var m=new VoiceCommandMessage{schema_version="1.0",message_type="voice_command",command_id="P2A-"+action,voice_text=action,action=action,direction=action=="STOP"?"ALL":"RIGHT",target_value=action=="STOP"?(float?)null:30,target_unit=action=="STOP"?null:"deg",parse_status="VALID"};using(var c=new TcpClient()){c.Connect("127.0.0.1",GameObject.Find("TowerCraneRoot").GetComponent<CommandReceiver>().Port);var b=Encoding.UTF8.GetBytes(JsonConvert.SerializeObject(m)+"\n");c.GetStream().Write(b,0,b.Length);}}
 static void Tick()
 {
  if(!Running||lastFrame==Time.frameCount)return;lastFrame=Time.frameCount;
  try{
   Require(Time.realtimeSinceStartup-started<240,"Worker tests timeout");Require(RootPose()==rootPose,"LIVE root changed");
   // Opening a Canvas registers its graphics on a rendered frame. Wait rather
