   if(pendingChoice>=0){if(Time.frameCount<choiceFrame)return;SelectRenderedCard(pendingChoice);pendingChoice=-1;stageFrame=Time.frameCount;return;}
   if(stage==0&&!e.Blending){Click("ChangeWorker");Require(ui.IsOpen&&e.WorkerModalOpen,"Worker modal did not open");Record("A1");Require(ui.CardCount==4&&agent.profiles.Select(p=>p.workerId).Distinct().Count()==4,"Four Worker cards missing");Record("A2");profileIndex=language=0;Advance(1);}
   else if(stage==1&&Time.frameCount-stageFrame>=3){Click("WorkerCard_"+agent.profiles[profileIndex].workerId);Click("WorkerLanguage_"+language);Require(Text("RoleName").text==agent.profiles[profileIndex].Name((WorkerLanguage)language),"Localized profile name wrong");Fonts();if(profileIndex==2&&language==2)ScreenCapture.CaptureScreenshot(Path.Combine(output,"Worker_Vietnamese.png"));language++;if(language==3){language=0;profileIndex++;}if(profileIndex==4){Record("A3",new{languages=3,profiles=4,localizedPages=12});Record("A28",new{coverage="visible Worker UI, all four profiles x KO/EN/VI, no auto-add"});ui.SetLanguage(WorkerLanguage.KO);profileIndex=0;Advance(2);}else Advance(1);}
   else if(stage==2){Choose(profileIndex);Advance(3);}
   else if(stage==3&&Time.frameCount-stageFrame>=3){var p=agent.profiles[profileIndex];Require(agent.ActiveProfile==p&&agent.ActiveState.workerId==p.workerId&&agent.HazardContext.workerId==p.workerId,"Active context not switched");Require(Text("WorkerContext").text.Contains(p.displayNameKo),"HUD not switched");Require(agent.ActiveVisual.GetComponentsInChildren<MeshFilter>().First().sharedMesh==p.avatarVisualPrefab.GetComponentsInChildren<MeshFilter>().First().sharedMesh,"Avatar prefab not switched");Require(agent.avatarRoot.childCount==1,"Multiple active visuals");Identity();Record(ProfileTests[profileIndex],new{p.workerId,p.roleCode,activeVisual=agent.ActiveVisual.name});ScreenCapture.CaptureScreenshot(Path.Combine(output,"Worker_"+p.roleCode+".png"));profileIndex++;if(profileIndex<4)Advance(2);else{Record("A8",new{characterCount=1,height,radius,center=V(center),step});Record("A9",new{eye,targetId,cameraId,interactionId});Require(agent.profiles.All(p=>p.avatarVisualPrefab.GetComponentsInChildren<CharacterController>(true).Length==0&&p.avatarVisualPrefab.GetComponentsInChildren<MonoBehaviour>(true).Length==0),"Inactive avatar contains controllers/logic");Record("A21");Choose(0);Advance(4);}}
   else if(stage==4&&Time.frameCount-stageFrame>=3){moveStart=e.player.position;e.CaptureCursor();Keys(Key.S);Advance(5);}
