   else if(stage==6&&Time.frameCount-stageFrame>=3){moveStart=e.player.position;e.CaptureCursor();Keys(Key.S);Advance(7);}
   else if(stage==7){Keys(Key.S);if(Vector3.Distance(moveStart,e.player.position)>=.65f){Keys();isolation=agent.StateFor("WKR_SIGNAL_01").routeSession.sampledPositions.Count==aCountBeforeB;agent.SaveActive();bCountAfter=agent.ActiveState.routeSession.sampledPositions.Count;Choose(0);Advance(8);}}
   else if(stage==8&&Time.frameCount-stageFrame>=4){float errorM=Vector3.Distance(positionA,e.player.position);Require(errorM<=.1f,"A->B->A restore exceeds 0.1m");Record("A10",new{expected=V(positionA),actual=V(e.player.position),errorM});Require(isolation&&agent.StateFor("WKR_RIG_01").routeSession.sampledPositions.Count==bCountAfter&&agent.states.Select(s=>s.routeSession).Distinct().Count()==4&&agent.states.All(s=>s.routeSession.workerId==s.workerId),"Worker route histories mixed/inactive sampled");var decimation=WorkerRouteSession.New("TEST-ONLY");for(int i=0;i<4005;i++)decimation.Append(new WorkerRoutePoint{position=new Vector3(i,0,0),timestampUtc="test-"+i,craneStage="NOT_EVALUATED",loadId="NOT_AVAILABLE"});Require(decimation.sampledPositions.Count<=2000&&decimation.sampledPositions.First().position.x==0&&decimation.sampledPositions.Last().position.x==4004&&decimation.decimationPasses>0,"Route decimation lost endpoints or cap");Record("A12",new{isolated=true,pointCap=2000,retained=decimation.sampledPositions.Count,decimation.decimationPasses});Click("CurrentWorkerRoutes");Advance(9);}
   else if(stage==9&&Time.frameCount-stageFrame>=3){Require(route.VisibleWorkerCount==1,"CURRENT shows inactive route");Record("A13");Click("AllWorkerRoutes");Advance(10);}
   else if(stage==10&&Time.frameCount-stageFrame>=3){Require(route.VisibleWorkerCount==4&&agent.profiles.Select(p=>p.routeLineStyle).Distinct().Count()==4&&agent.profiles.Select(p=>p.icon).Distinct().Count()==4,"ALL route identification missing");Record("A14",new{workers=4,labels=agent.profiles.Select(p=>p.workerId),patterns=agent.profiles.Select(p=>p.Pattern)});Require(Text("RouteOverlayDisclosure").text==ui.Catalog.Get("allDisclosure",agent.selection.language),"ALL DEMO disclosure missing");Record("A15");var engine=e.hazard.route;var zone=engine.zones.First(z=>z.kind==RouteHazardKind.HotWork);var candidate=new[]{zone.center+Vector3.left,zone.center+Vector3.right};float signal=WorkerCandidateRouteCost.Evaluate(agent.profiles[0],candidate,engine),weld=WorkerCandidateRouteCost.Evaluate(agent.profiles[2],candidate,engine);Require(Mathf.Abs(signal-weld)>.01f,"Role candidate cost bias did not differ");Record("A16",new{plannerSupportsRolePreference=false,newPathfinding=false,signalCost=signal,welderCost=weld});Require(!UnityEngine.Object.FindObjectsByType<Transform>(FindObjectsInactive.Include,FindObjectsSortMode.None).Any(t=>t.name.Contains("LiftExclusion")),"2B exclusion zone created");Record("A16-1");Require(agent.states.SelectMany(s=>s.routeSession.sampledPositions).All(p=>p.craneStage=="NOT_EVALUATED"),"2A guessed crane stage");Record("A16-2");unsafeIndex=0;InjectUnsafe();}
   else if(stage==11&&Time.frameCount-stageFrame>=4){Require(agent.IsSafePosition(e.player.position),"Restore remained unsafe");var correction=agent.ActiveState.positionCorrections.Last();float d=Vector2.Distance(new Vector2(correction.requested.x,correction.requested.z),new Vector2(correction.restored.x,correction.restored.z));Require(d<=3.001f||correction.reason.Contains("SPAWN"),"Restore ignored 3m/fallback policy");corrections.Add(new{kind=new[]{"WALL","SEA","DOOR_FRAME"}[unsafeIndex],requested=V(correction.requested),restored=V(correction.restored),distanceXZ=d,correction.reason});Choose(0);Advance(12);}
