   else if(stage==15&&Time.frameCount-stageFrame>=4){var adapter=new WorkerAccidentRoleAdapter(ui.accidentRepository);Require(agent.profiles[0].accidentRoleCode=="2"&&agent.profiles[1].accidentRoleCode=="3"&&adapter.Matches(agent.profiles[0]).All(r=>r.workerRoleCode=="2")&&adapter.Matches(agent.profiles[0]).Count>0&&adapter.Matches(agent.profiles[1]).Count>0,"CM-H04 mapping wrong");Record("A26",new{signalerCases=adapter.Matches(agent.profiles[0]).Count,riggerCases=adapter.Matches(agent.profiles[1]).Count});Require(agent.profiles.Skip(2).All(p=>p.accidentRoleCode=="NOT_MAPPED"&&adapter.Matches(p).Count==0),"Uncertain role mapped");Click("ChangeWorker");Advance(151);}
   else if(stage==151&&Time.frameCount-stageFrame>=3){Click("WorkerCard_WKR_WELD_01");Require(Text("RoleAccidentMapping").text==ui.Catalog.Get("noRoleData",agent.selection.language),"Missing role data UI dishonest");Record("A27");ui.Close();ui.SetRouteView(WorkerRouteView.ALL);Advance(16);}
