 static void Finish()
 {
  EditorApplication.update-=Tick;Running=false;Keys();if(ui.IsOpen)ui.Close();InputSystem.RemoveDevice(keyboard);InputSystem.settings=original;original.hideFlags=flags;UnityEngine.Object.DestroyImmediate(temp);foreach(var d in physical)if(d.added)InputSystem.EnableDevice(d);if(e.IsExploring)e.Exit();Application.runInBackground=background;Application.targetFrameRate=rate;
  File.WriteAllText(Path.Combine(output,"Phase2A_tests.json"),JsonConvert.SerializeObject(new{passed=error==null,error,cleanupVerified=InputSystem.settings==original,rootUnchanged=RootPose()==rootPose,rows},Formatting.Indented));
